$next='/aluno/teste.php?id='.$id.'&view='.rawurlencode($view);if(!$student){header('Location: /aluno/login.php?next='.rawurlencode($next),true,303);exit;}$studentId=(int)$student['id'];$record=student_test_for_student($db,$id,$studentId);
if(!$record){http_response_code(404);student_shell_start('Registro não encontrado',null,$student);?><div class="student-empty">Registro não encontrado.</div><?php student_shell_end();exit;}
$error='';$contextScope=(string)($record['context_scope']??'course');
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!verify_csrf('student-process-'.$id,$_POST['_csrf']??null))$error='Solicitação inválida.';
    else try{
        $action=(string)($_POST['action']??'');
        if($action==='save_exposure'){student_test_update_exposure($db,$id,$studentId,$_POST);$view='process';$_SESSION['student_process_notice']='Exposição salva. Agora escolha como registrar o processamento.';}
        elseif($action==='add_step'){
            $stageKey=(string)($_POST['stage_key']??'');student_process_add_guided_step($db,$id,$studentId,$_POST);
            if($stageKey==='dry'){$view='review';$_SESSION['student_process_notice']='Secagem registrada. Complete o resultado para fechar este registro.';}
            else{$view='process';$_SESSION['student_process_notice']='Etapa registrada.';}
        }
        elseif($action==='delete_step'){student_process_delete_from_step($db,$id,(int)($_POST['step_id']??0),$studentId);$view='process';$_SESSION['student_process_notice']='Última etapa desfeita.';}
        elseif($action==='save_result'){$notes=student_workspace_text($_POST['notes']??'',4000);$db->prepare('UPDATE student_tests SET notes=?,updated_at=? WHERE id=? AND student_id=?')->execute([$notes,utc_now(),$id,$studentId]);$view='review';$_SESSION['student_process_notice']='Resultado salvo.';}
        elseif($action==='upload'){
            $phase=(string)($_POST['phase']??'result');
            if($phase==='scene')student_test_update_exposure($db,$id,$studentId,$_POST);
            else{$notes=student_workspace_text($_POST['notes']??'',4000);$db->prepare('UPDATE student_tests SET notes=?,updated_at=? WHERE id=? AND student_id=?')->execute([$notes,utc_now(),$id,$studentId]);}
            $file=$_FILES['image']??null;if(!is_array($file))throw new RuntimeException('Selecione uma imagem.');student_test_add_media_phase($db,$id,$studentId,$file,$phase);$view=$phase==='scene'?'exposure':'review';$_SESSION['student_process_notice']='Imagem adicionada.';
        }
        elseif($action==='delete_media'){student_test_delete_media($db,(int)($_POST['media_id']??0),$studentId);$view=(string)($_POST['phase']??'result')==='scene'?'exposure':'review';$_SESSION['student_process_notice']='Imagem removida.';}
        elseif($action==='submit'){if($contextScope!=='course')throw new RuntimeException('Registros pessoais não são enviados para avaliação.');student_test_submit($db,$id,$studentId);$view='review';$_SESSION['student_process_notice']='Registro enviado para avaliação.';}
        elseif($action==='message'){student_test_add_student_message($db,$id,$studentId,(string)($_POST['message']??''));$view='review';$_SESSION['student_process_notice']='Mensagem enviada.';}
        else throw new RuntimeException('Ação inválida.');
        header('Location: /aluno/teste.php?id='.$id.'&view='.$view,true,303);exit;
    }catch(Throwable $e){$error=$e->getMessage();}
}
$record=student_test_for_student($db,$id,$studentId)??$record;$steps=student_process_steps($db,$id);$complete=student_experience_process_complete($steps);$nextChoices=student_experience_next_choices($steps);$media=student_test_media($db,$id);$sceneMedia=student_test_media_by_phase($media,'scene');$resultMedia=student_test_media_by_phase($media,'result');$inventory=student_inventory_items($db,$studentId);$preparations=student_saved_preparations($db,$studentId);$messages=student_test_messages($db,$id);$notice=(string)($_SESSION['student_process_notice']??'');unset($_SESSION['student_process_notice']);$locked=(string)$record['status']==='reviewed';$developers=student_process_developer_catalog();$lastStep=$steps?($steps[array_key_last($steps)]??null):null;$resultReady=$complete||$locked||$resultMedia||trim((string)$record['notes'])!==''||in_array((string)$record['status'],['submitted','needs_revision','reviewed'],true);
$plan=student_process_plan_for_test($db,$id,$studentId);$planSteps=$plan?student_process_plan_steps($db,(int)$plan['id']):[];$planNext=$plan?student_process_plan_next_step($db,$plan):null;$planCompleted=0;foreach($planSteps as $planStep)if((string)$planStep['status']==='completed')$planCompleted++;$planStarted=$plan&&((string)$plan['status']!=='planned'||$planCompleted>0);
$firstDevelopment=null;$bleachNames=[];foreach($steps as $step){$stageKey=(string)$step['stage_key'];if($firstDevelopment===null&&$stageKey==='first_development')$firstDevelopment=$step;if(in_array($stageKey,['ferric','peracetic','dichromate','permanganate'],true)&&trim((string)$step['chemical_name'])!=='')$bleachNames[]=(string)$step['chemical_name'];}$bleachNames=array_values(array_unique($bleachNames));
student_shell_start((string)$record['title'].' · Caderno',null,$student);?>
