<?php if($contextScope==='course'):?><section class="student-review-thread"><p class="student-kicker">Curso</p><h3>Avaliação</h3><p class="student-review-help">Quando exposição, processamento e resultado estiverem registrados, envie o conjunto para avaliação.</p><?php if(!$locked&&$record['status']!=='submitted'):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-process-'.$id))?>"><input type="hidden" name="action" value="submit"><button class="button button-primary" type="submit">Enviar para avaliação</button></form><?php else:?><p>Registro enviado ou revisado.</p><?php endif;?><details class="student-optional-fields"<?=$messages?' open':''?>><summary>Conversa<?=$messages?' · '.count($messages):''?></summary><?php if($messages):?><div class="student-message-list"><?php foreach($messages as $message):?><article><strong><?=$message['author_role']==='admin'?'Professor':'Você'?></strong><p><?=nl2br(h((string)$message['body']))?></p><small><?=h(student_test_message_date((string)$message['created_at']))?></small></article><?php endforeach;?></div><?php endif;?><form method="post" class="student-form-grid"><input type="hidden" name="_csrf" value="<?=h(csrf_token('student-process-'.$id))?>"><input type="hidden" name="action" value="message"><label class="form-field student-span-2">Mensagem<textarea name="message" rows="3"></textarea></label><button class="button button-secondary" type="submit">Enviar mensagem</button></form></details></section><?php endif;?></div></section>
<?php endif;?>
<?php student_shell_end();
function student_process_inventory_select_html(array $inventory,string $label,bool $simple=false): string {if(!$inventory)return '';ob_start();?><label class="form-field student-span-2"<?=$simple?'':' data-developer-inventory'?>><?=h($label)?><select name="<?=$simple?'inventory_item_id_simple':'inventory_item_id'?>"><option value="">Não vincular ao inventário</option><?php foreach($inventory as $item):?><option value="<?=(int)$item['id']?>"><?=h((string)$item['name'])?> · <?=h(student_workbench_number((float)$item['quantity']).' '.$item['unit'])?></option><?php endforeach;?></select></label><?php return (string)ob_get_clean();}
